"""Conversation-first local dashboard markup for FERMiON."""

PAGE = r'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FERMiON</title>
  <style>
    :root{color-scheme:dark;--bg:#090d12;--surface:#0f151d;--raised:#151d27;--line:#283442;--text:#edf3f8;--muted:#8e9ba9;--accent:#69e1d8;--warn:#f1b866;--danger:#f18484;--ok:#7bd99a}
    *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 Inter,"Segoe UI",sans-serif}button,textarea{font:inherit}.app{height:100svh;display:grid;grid-template-columns:238px minmax(0,1fr) 310px}.rail,.context{background:var(--surface);padding:24px 20px;overflow:auto}.rail{border-right:1px solid var(--line);display:flex;flex-direction:column}.context{border-left:1px solid var(--line)}.brand{font-size:21px;font-weight:750;letter-spacing:.18em}.brand small{display:block;margin-top:2px;color:var(--accent);font-size:10px;letter-spacing:.12em}.sectionLabel{margin:28px 0 9px;color:var(--muted);font-size:10px;font-weight:700;letter-spacing:.14em;text-transform:uppercase}.modelState{display:flex;align-items:center;gap:8px}.dot{width:8px;height:8px;border-radius:50%;background:var(--muted)}.dot.ready{background:var(--ok);box-shadow:0 0 0 4px #7bd99a18}.muted{color:var(--muted)}.mini{font-size:12px}.rail button,.secondary{width:100%;margin-top:8px;padding:9px 10px;border:1px solid var(--line);border-radius:6px;background:transparent;color:var(--text);text-align:left;cursor:pointer}.rail button:hover,.secondary:hover{border-color:var(--accent);color:var(--accent)}.guard{margin-top:auto;padding-top:20px;color:var(--muted);font-size:11px}.workspace{min-width:0;display:flex;flex-direction:column}.chatHead{height:72px;padding:17px 28px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.chatHead h1{font-size:16px;margin:0}.chatHead p{font-size:12px;color:var(--muted);margin:2px 0 0}.clear{border:0;background:transparent;color:var(--muted);cursor:pointer}.clear:hover{color:var(--text)}.messages{flex:1;overflow:auto;padding:34px max(28px,calc((100% - 760px)/2));scroll-behavior:smooth}.empty{max-width:650px;margin:8vh auto 0}.empty h2{font-size:34px;line-height:1.12;letter-spacing:-.025em;margin:0 0 12px}.empty p{color:var(--muted);font-size:15px;max-width:560px}.suggestions{display:flex;gap:8px;flex-wrap:wrap;margin-top:24px}.suggestions button{border:1px solid var(--line);border-radius:999px;background:transparent;color:var(--muted);padding:8px 12px;cursor:pointer}.suggestions button:hover{color:var(--accent);border-color:var(--accent)}.message{max-width:760px;margin:0 auto 22px;animation:enter .18s ease-out}.message .who{font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:6px}.message .body{font-size:15px;white-space:pre-wrap}.message.user .body{color:#cbd5df}.message.assistant{padding-left:16px;border-left:2px solid var(--accent)}@keyframes enter{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}.composerWrap{padding:14px max(20px,calc((100% - 800px)/2)) 22px;background:linear-gradient(transparent,var(--bg) 18%)}.composer{border:1px solid var(--line);border-radius:10px;background:var(--raised);padding:12px;transition:border-color .15s}.composer:focus-within{border-color:#4a6572}.composer textarea{display:block;width:100%;min-height:58px;max-height:180px;resize:vertical;border:0;outline:0;background:transparent;color:var(--text)}.composeBar{display:flex;align-items:center;justify-content:space-between;gap:12px}.approve{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:12px}.approve input{accent-color:var(--warn)}.send{border:0;border-radius:6px;background:var(--accent);color:#061110;font-weight:750;padding:9px 16px;cursor:pointer}.send:disabled{opacity:.45;cursor:wait}.context h2{font-size:16px;margin:0}.count{color:var(--muted);font-size:12px;margin-top:3px}.capability{border-top:1px solid var(--line);padding:13px 0}.capability summary{cursor:pointer;font-weight:650;list-style:none}.capability summary::after{content:'+';float:right;color:var(--muted)}.capability[open] summary::after{content:'−'}.capability p{color:var(--muted);font-size:12px}.op{padding:7px 0;color:#c8d2dc;font-size:12px}.op b{color:var(--accent);font-weight:600}.op em{color:var(--warn);font-style:normal;margin-left:5px}.audit{margin-top:24px}.audit pre{max-height:260px;overflow:auto;background:#080c11;border:1px solid var(--line);padding:10px;color:#aab8c6;font:11px/1.45 "Cascadia Code",monospace;white-space:pre-wrap}.statusNote{margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}
    @media(max-width:980px){.app{grid-template-columns:190px minmax(0,1fr)}.context{display:none}}@media(max-width:680px){.app{display:block;height:auto;min-height:100svh}.rail{display:none}.workspace{min-height:100svh}.chatHead{padding:14px 18px}.messages{padding:24px 18px}.empty h2{font-size:28px}.composerWrap{padding:12px}.composeBar{align-items:flex-end}.approve{max-width:210px}}
    @media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}
  </style>
</head>
<body><main class="app">
  <aside class="rail">
    <div class="brand">FERMiON<small>LOCAL INTELLIGENCE</small></div>
    <div class="sectionLabel">Model</div>
    <div class="modelState"><span class="dot" id="modelDot"></span><span id="modelState">Checking…</span></div>
    <div class="muted mini" id="modelName">Local model</div>
    <button onclick="runOperation('llm_start')">Start local model</button>
    <button onclick="runOperation('llm_stop')">Stop local model</button>
    <div class="sectionLabel">God's Eye View</div>
    <div class="modelState"><span class="dot" id="gevDot"></span><span id="gevState">Checking…</span></div>
    <div class="muted mini" id="gevUrl">http://127.0.0.1:4173/</div>
    <button onclick="runOperation('gev_start')">Start globe</button>
    <button onclick="runOperation('gev_stop')">Stop globe</button>
    <div class="sectionLabel">Verified operations</div>
    <button onclick="runOperation('reference')">Verify reference specimen</button>
    <button onclick="runOperation('regression')">Run deterministic tests</button>
    <label class="approve"><input id="confirm" type="checkbox">Allow the opt-in desktop test</label>
    <button onclick="runOperation('live_gate')">Run live Notepad gate</button>
    <div class="guard"><span id="writeAuthority">Checking workspace authority…</span><br><br>Localhost only. Workspace creates and updates remain validated and audited. Deletes, renames, launches, frozen protocols, and external paths require separate authority.</div>
  </aside>

  <section class="workspace">
    <header class="chatHead"><div><h1>Conversation</h1><p id="project">Loading local workspace…</p></div><button class="clear" onclick="clearConversation()">Clear</button></header>
    <div class="messages" id="messages">
      <div class="empty" id="emptyState"><h2>Ask FERMiON to explain, inspect, plan, or act.</h2><p>It can use every registered application adapter. Read-only work can be planned directly; state-changing work stays behind explicit approval.</p><div class="suggestions"><button onclick="suggest(this)">What can you do?</button><button onclick="suggest(this)">List the programs you can access</button><button onclick="suggest(this)">Show the self-evolver status</button><button onclick="suggest(this)">Show the gods eye view status</button><button onclick="suggest(this)">Explain the current safety state</button></div></div>
    </div>
    <div class="composerWrap"><div class="composer"><textarea id="message" aria-label="Message FERMiON" placeholder="Message FERMiON…"></textarea><div class="composeBar"><label class="approve"><input id="authorize" type="checkbox">Approve validated actions in this request</label><button class="send" id="send" onclick="runAgent()">Send</button></div></div></div>
  </section>

  <aside class="context">
    <h2>Built-in capabilities</h2><div class="count" id="capabilityCount">Loading registry…</div><div id="capabilities"></div>
    <div class="audit"><div class="sectionLabel">Plan &amp; audit details</div><pre id="details">No plan yet.</pre></div>
    <div class="statusNote mini muted" id="runStatus">No operation running.</div>
  </aside>
</main>
<script>
const transcript=[];let active=null;
const messages=document.getElementById('messages'),box=document.getElementById('message'),send=document.getElementById('send');
function addMessage(role,content){document.getElementById('emptyState')?.remove();const node=document.createElement('article');node.className='message '+role;const who=document.createElement('div');who.className='who';who.textContent=role==='user'?'You':'FERMiON';const body=document.createElement('div');body.className='body';body.textContent=content;node.append(who,body);messages.appendChild(node);messages.scrollTop=messages.scrollHeight;transcript.push({role,content});return body}
function clearConversation(){transcript.length=0;messages.innerHTML='<div class="empty" id="emptyState"><h2>Start a new conversation.</h2><p>Ask a question or describe a task. FERMiON will use only its registered capabilities.</p></div>';document.getElementById('details').textContent='No plan yet.'}
function suggest(button){box.value=button.textContent;box.focus()}
function agentSummary(data){const actions=data.plan?.actions||[];if(data.requires_approval)return (data.reply||data.plan?.summary||'The plan is ready.')+'\n\nApproval is required before I can make those changes.';if(data.mode==='typed_read_only'&&data.reply)return data.reply;if(data.reply&&!data.executed)return data.reply;if(!data.validation?.valid)return 'I could not validate that plan: '+(data.validation.reasons||[]).join('; ');if(!data.executed)return data.plan?.summary||'The plan is ready. Approve it only if you want the validated actions executed.';const records=data.report?.records||[];const listed=records.flatMap(r=>r.result?.details?.programs||[]);if(listed.length)return 'I can access these registered programs:\n\n'+listed.map(p=>'• '+p.alias.replaceAll('_',' ')).join('\n');const failed=records.find(r=>!r.verification?.success);if(failed)return 'I stopped because '+(failed.verification.reason||failed.result?.error||'verification failed')+'. Reversible changes were rolled back.';return (data.plan?.summary?data.plan.summary+'\n\n':'')+'Completed '+records.length+' validated action'+(records.length===1?'':'s')+'. All recorded checks passed.'}
async function runAgent(){const message=box.value.trim();if(!message||send.disabled)return;const history=transcript.slice(-12);addMessage('user',message);box.value='';send.disabled=true;const pending=addMessage('assistant','Thinking with the registered capability set…');try{const response=await fetch('/api/agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,history,execute:document.getElementById('authorize').checked})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');const reply=agentSummary(data);pending.textContent=reply;transcript[transcript.length-1].content=reply;document.getElementById('details').textContent=JSON.stringify(data,null,2);document.getElementById('authorize').checked=false}catch(error){pending.textContent='I could not complete that request: '+error.message;transcript[transcript.length-1].content=pending.textContent}finally{send.disabled=false;box.focus()}}
async function loadCapabilities(){try{const data=await fetch('/api/capabilities').then(r=>r.json());document.getElementById('capabilityCount').textContent=data.application_count+' applications · '+data.operation_count+' operations';const host=document.getElementById('capabilities');for(const app of data.applications){const details=document.createElement('details');details.className='capability';const summary=document.createElement('summary');summary.textContent=app.name.replaceAll('_',' ');details.appendChild(summary);if(app.description){const p=document.createElement('p');p.textContent=app.description;details.appendChild(p)}for(const capability of app.capabilities){const op=document.createElement('div');op.className='op';const name=document.createElement('b');name.textContent=capability.operation;op.appendChild(name);if(capability.mutating){const tag=document.createElement('em');tag.textContent='approval';op.appendChild(tag)}if(capability.description)op.appendChild(document.createTextNode(' — '+capability.description));details.appendChild(op)}host.appendChild(details)}}catch(error){document.getElementById('capabilityCount').textContent='Registry unavailable: '+error.message}}
async function state(){const s=await fetch('/api/status').then(r=>r.json());document.getElementById('project').textContent=s.project;const ready=s.model.healthy;document.getElementById('modelState').textContent=ready?'Ready':s.model.running?'Starting':'Stopped';document.getElementById('modelDot').className='dot '+(ready?'ready':'');document.getElementById('modelName').textContent=s.model.identifier||(s.model.path?s.model.path.split('\\').pop():'Not configured');document.getElementById('writeAuthority').textContent=s.workspace_write?.authorized?'Owner-authorized workspace writes are active.':'Workspace writes require per-request approval.';const g=s.gods_eye_view||{};document.getElementById('gevState').textContent=g.healthy?'Ready':g.running?'Starting':g.configured?'Stopped':'Unavailable';document.getElementById('gevDot').className='dot '+(g.healthy?'ready':'');if(g.url)document.getElementById('gevUrl').textContent=g.url}
async function runOperation(operation){if(operation==='live_gate'&&!document.getElementById('confirm').checked){addMessage('assistant','The live desktop gate needs its separate confirmation first.');return}const status=document.getElementById('runStatus');status.textContent='Starting '+operation+'…';const response=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,live_confirmed:document.getElementById('confirm').checked})});const data=await response.json();if(!response.ok){status.textContent=data.error;return}active=data.id;pollOperation()}
async function pollOperation(){if(!active)return;const job=await fetch('/api/jobs/'+active).then(r=>r.json());document.getElementById('runStatus').textContent=job.operation+': '+job.status+(job.return_code===null?'':' · exit '+job.return_code);if(job.status==='running')setTimeout(pollOperation,700);else state()}
box.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();runAgent()}});
state();loadCapabilities();box.focus();
</script></body></html>'''
